def seed():
    init_db()
    db = SessionLocal()
    try:
        existing = db.query(Scheme).count()
        if existing > 0:
            print(f"Database already has {existing} schemes. Skipping seed.")
            return
        added = 0
        for s in SCHEMES:
            deadline = None
            if s.get("deadline"):
                try:
                    deadline = datetime.strptime(s["deadline"], "%Y-%m-%d")
                except Exception:
                    pass
            scheme = Scheme(
                name=s["name"], short_name=s.get("short_name"),
                description=s["description"], category=s["category"],
                ministry=s.get("ministry"), benefits=s["benefits"],
                subsidy_amount=s.get("subsidy_amount"), max_benefit=s.get("max_benefit"),
                eligibility=s["eligibility"], min_land=s.get("min_land"),
                max_land=s.get("max_land"), max_income=s.get("max_income"),
                farmer_category=s.get("farmer_category", "all"),
                documents_needed=s["documents_needed"],
                deadline=deadline, is_active=True,
                applicable_states=s.get("applicable_states", "All"),
                apply_url=s.get("apply_url"), helpline=s.get("helpline"),
            )
            db.add(scheme)
            added += 1
        db.commit()
        print(f"✅ Seeded {added} government schemes successfully.")
    finally:
        db.close()


if __name__ == "__main__":
    seed()
